// Whole-£ text inputs shown with thousands separators (e.g. 1,500,000)
function parseMoneyInput(el) {
  return Number(String(el?.value ?? '').replace(/,/g, '')) || 0;
}

function formatMoneyValue(pounds) {
  return Math.round(pounds).toLocaleString('en-GB');
}

// Re-format as the user types, keeping the caret after the same digit
function attachMoneyFormatting(el) {
  if (!el) return;
  el.addEventListener('input', () => {
    const raw = el.value;
    const caret = el.selectionStart ?? raw.length;
    const digitsBeforeCaret = raw.slice(0, caret).replace(/\D/g, '').length;
    const negative = raw.trim().startsWith('-');
    const digits = raw.replace(/\D/g, '');
    const formatted = (negative ? '-' : '') + (digits ? Number(digits).toLocaleString('en-GB') : '');
    el.value = formatted;

    let pos = negative ? 1 : 0;
    let seen = 0;
    while (pos < formatted.length && seen < digitsBeforeCaret) {
      if (/\d/.test(formatted[pos])) seen++;
      pos++;
    }
    el.setSelectionRange(pos, pos);
  });
}

function formatCurrencyK(k) {
  if (isNaN(k) || !isFinite(k)) return '£0';
  const full = Math.round(k * 1000);
  return (full < 0 ? '-' : '') + '£' + Math.abs(full).toLocaleString();
}

function getProjectCostK() {
  return Math.max(0, parseMoneyInput(document.getElementById('project-cost-input'))) / 1000;
}

function getBaselineDepreciationK() {
  return parseMoneyInput(document.getElementById('dep-baseline')) / 1000;
}

// Baseline depreciation applies to every year in both scenarios; Scenario 2 adds the project cost
// straight-lined over Y1-Y3
function getDepreciationK() {
  const base = getBaselineDepreciationK();
  const projectShare = getProjectCostK() / 3;
  return {
    s1: [base, base, base, base],
    s2: [base, base + projectShare, base + projectShare, base + projectShare]
  };
}

function updateSummaryTable() {
  const tableMap = {
    s1Emp: ['s1-emp-baseline', 's1-emp-y1', 's1-emp-y2', 's1-emp-y3'],
    s1Prof: ['s1-prof-baseline', 's1-prof-y1', 's1-prof-y2', 's1-prof-y3'],
    s1Dep: ['s1-dep-baseline', 's1-dep-y1', 's1-dep-y2', 's1-dep-y3'],
    s2Emp: ['s2-emp-baseline', 's2-emp-y1', 's2-emp-y2', 's2-emp-y3'],
    s2Prof: ['s2-prof-baseline', 's2-prof-y1', 's2-prof-y2', 's2-prof-y3'],
    s2Dep: ['s2-dep-baseline', 's2-dep-y1', 's2-dep-y2', 's2-dep-y3'],
    gva: ['gva-baseline', 'gva-y1', 'gva-y2', 'gva-y3']
  };

  const dep = getDepreciationK();
  let totalGvaY1toY3 = 0;

  for (let i = 0; i < 4; i++) {
    document.getElementById(tableMap.s1Emp[i]).textContent =
      employeeCostK.s1[i] ? formatCurrencyK(employeeCostK.s1[i]) : '£0';
    document.getElementById(tableMap.s1Prof[i]).textContent =
      netProfitK.s1[i] ? formatCurrencyK(netProfitK.s1[i]) : '£0';

    document.getElementById(tableMap.s2Emp[i]).textContent =
      employeeCostK.s2[i] ? formatCurrencyK(employeeCostK.s2[i]) : '£0';
    document.getElementById(tableMap.s2Prof[i]).textContent =
      netProfitK.s2[i] ? formatCurrencyK(netProfitK.s2[i]) : '£0';

    document.getElementById(tableMap.s1Dep[i]).textContent = formatCurrencyK(dep.s1[i]);
    document.getElementById(tableMap.s2Dep[i]).textContent = formatCurrencyK(dep.s2[i]);

    const totalS1 = (employeeCostK.s1[i] || 0) + (netProfitK.s1[i] || 0) + dep.s1[i];
    const totalS2 = (employeeCostK.s2[i] || 0) + (netProfitK.s2[i] || 0) + dep.s2[i];
    const gvaK = totalS2 - totalS1;
    document.getElementById(tableMap.gva[i]).textContent = formatCurrencyK(gvaK);

    if (i >= 1 && i <= 3) {
      totalGvaY1toY3 += gvaK;
    }

    if (typeof highlightCellIfInvalid === 'function') {
      const s1Rev = scenario1 ? scenario1.getData()[i].value : 4500;
      const s2Rev = scenario2 ? scenario2.getData()[i].value : 4500;

      const s1EmpVal = employeeCostK.s1[i] || 0;
      const s1ProfVal = netProfitK.s1[i] || 0;
      const s2EmpVal = employeeCostK.s2[i] || 0;
      const s2ProfVal = netProfitK.s2[i] || 0;

      const s1EmpCostHigher = s1EmpVal > s1Rev;
      const s1ProfitTooHigh = s1ProfVal > (s1Rev - s1EmpVal);
      highlightCellIfInvalid(document.getElementById(tableMap.s1Emp[i]), s1EmpCostHigher);
      highlightCellIfInvalid(document.getElementById(tableMap.s1Prof[i]), s1EmpCostHigher || s1ProfitTooHigh);

      const s2EmpCostHigher = s2EmpVal > s2Rev;
      const s2ProfitTooHigh = s2ProfVal > (s2Rev - s2EmpVal);
      highlightCellIfInvalid(document.getElementById(tableMap.s2Emp[i]), s2EmpCostHigher);
      highlightCellIfInvalid(document.getElementById(tableMap.s2Prof[i]), s2EmpCostHigher || s2ProfitTooHigh);
    }
  }

  // Project cost already reaches GVA through Scenario 2 depreciation, so it is not added again here
  const totalGva = totalGvaY1toY3;

  const totalGvaEl = document.getElementById('total-gva');
  if (totalGvaEl) {
    totalGvaEl.textContent = formatCurrencyK(totalGva);
  }
  if (typeof runComparisonSanityChecks === 'function') {
    runComparisonSanityChecks();
  }
}

const COMP_KEYS = [
  'comp-s1-emp-baseline', 'comp-s1-emp-y1', 'comp-s1-emp-y2', 'comp-s1-emp-y3',
  'comp-s1-prof-baseline', 'comp-s1-prof-y1', 'comp-s1-prof-y2', 'comp-s1-prof-y3',
  'comp-s2-emp-baseline', 'comp-s2-emp-y1', 'comp-s2-emp-y2', 'comp-s2-emp-y3',
  'comp-s2-prof-baseline', 'comp-s2-prof-y1', 'comp-s2-prof-y2', 'comp-s2-prof-y3',
  'comp-gva-baseline', 'comp-gva-y1', 'comp-gva-y2', 'comp-gva-y3',
  'comp-project-cost'
];

function updateComparisonCalculations(e) {
  const targetId = e ? e.target.id : null;

  const getValue = (id) => {
    const el = document.getElementById(id);
    return el && el.value !== '' ? Number(el.value) : null;
  };

  const setValue = (id, val) => {
    const el = document.getElementById(id);
    if (el) el.value = val !== null ? val : '';
  };

  const columns = ['baseline', 'y1', 'y2', 'y3'];
  let totalGvaY1toY3 = 0;

  columns.forEach((col, idx) => {
    const s1Emp = getValue(`comp-s1-emp-${col}`);
    const s1Prof = getValue(`comp-s1-prof-${col}`);
    const s2Emp = getValue(`comp-s2-emp-${col}`);
    const s2Prof = getValue(`comp-s2-prof-${col}`);
    const gvaId = `comp-gva-${col}`;

    if (targetId !== gvaId) {
      if (s1Emp !== null || s1Prof !== null || s2Emp !== null || s2Prof !== null) {
        const totalS1 = (s1Emp || 0) + (s1Prof || 0);
        const totalS2 = (s2Emp || 0) + (s2Prof || 0);
        const calcGva = totalS2 - totalS1;
        setValue(gvaId, calcGva);
      }
    }

    const gvaVal = getValue(gvaId);
    if (idx >= 1 && idx <= 3 && gvaVal !== null) {
      totalGvaY1toY3 += gvaVal;
    }

    if (typeof highlightIfInvalid === 'function') {
      const s1Rev = scenario1 ? scenario1.getData()[idx].value : 4500;
      const s2Rev = scenario2 ? scenario2.getData()[idx].value : 4500;

      const s1EmpVal = s1Emp || 0;
      const s1ProfVal = s1Prof || 0;
      const s2EmpVal = s2Emp || 0;
      const s2ProfVal = s2Prof || 0;

      const s1EmpCostHigher = s1EmpVal > s1Rev;
      const s1ProfitTooHigh = s1ProfVal > (s1Rev - s1EmpVal);
      highlightIfInvalid(document.getElementById(`comp-s1-emp-${col}`), s1EmpCostHigher);
      highlightIfInvalid(document.getElementById(`comp-s1-prof-${col}`), s1EmpCostHigher || s1ProfitTooHigh);

      const s2EmpCostHigher = s2EmpVal > s2Rev;
      const s2ProfitTooHigh = s2ProfVal > (s2Rev - s2EmpVal);
      highlightIfInvalid(document.getElementById(`comp-s2-emp-${col}`), s2EmpCostHigher);
      highlightIfInvalid(document.getElementById(`comp-s2-prof-${col}`), s2EmpCostHigher || s2ProfitTooHigh);
    }
  });

  const projCost = getValue('comp-project-cost') || 0;

  const calculatedTotalGva = totalGvaY1toY3 + projCost;
  animateGvaValue('comp-total-gva', calculatedTotalGva);

  if (typeof runComparisonSanityChecks === 'function') {
    runComparisonSanityChecks();
  }
}

function clearComparisonInputs() {
  COMP_KEYS.forEach(key => {
    const el = document.getElementById(key);
    if (el) el.value = key === 'comp-project-cost' ? '0' : '';
  });
  const compTotalGvaEl = document.getElementById('comp-total-gva');
  if (compTotalGvaEl) compTotalGvaEl.textContent = '–';
}


function animateGvaValue(elementId, endK) {
  const element = document.getElementById(elementId);
  if (!element) return;
  if (isNaN(endK) || !isFinite(endK)) {
    element.textContent = '£0';
    return;
  }
  element.textContent = formatCurrencyK(endK);
}

function createScenarioChart({ svgId, summaryId, title, series, onUpdate }) {
  const svg = document.getElementById(svgId);
  const summary = document.getElementById(summaryId);
  const NS = 'http://www.w3.org/2000/svg';
  const plot = { left: 72, top: 26, width: 500, height: 135, right: 572, bottom: 161 };
  const plotMidY = plot.top + plot.height / 2;
  let maxRevenue = 10000;
  let minRevenue = 200;
  const data = series.map(item => ({ ...item }));
  const xStep = plot.width / (data.length - 1);
  const pointElements = [];
  const tagElements = [];

  svg.innerHTML = `
    <defs>
      <clipPath id="clip-${svgId}">
        <rect x="${plot.left}" y="${plot.top}" width="${plot.width}" height="${plot.height}" rx="12" ry="12"></rect>
      </clipPath>
    </defs>
    <g class="grid"></g>
    <g class="axes"></g>
    <path class="area" clip-path="url(#clip-${svgId})"></path>
    <path class="trend" clip-path="url(#clip-${svgId})"></path>
    <g class="points"></g>
    <g class="x-labels"></g>
    <g class="y-labels"></g>
    <text x="20" y="${plotMidY}" class="label y-axis-title">Revenue</text>
    <text x="296" y="${plot.bottom + 46}" class="label">Time</text>
  `;

  const gridGroup = svg.querySelector('.grid');
  const axesGroup = svg.querySelector('.axes');
  const area = svg.querySelector('.area');
  const line = svg.querySelector('.trend');
  const pointsGroup = svg.querySelector('.points');
  const xLabelsGroup = svg.querySelector('.x-labels');
  const yLabelsGroup = svg.querySelector('.y-labels');
  const yAxisTitle = svg.querySelector('.y-axis-title');

  function make(tag, attrs = {}, parent) {
    const el = document.createElementNS(NS, tag);
    Object.entries(attrs).forEach(([k, v]) => el.setAttribute(k, v));
    if (parent) parent.appendChild(el);
    return el;
  }
  const isChart2 = (svgId === 'chart2');
  const isEditable = (i) => !(isChart2 && i === 0);

  summary.innerHTML = data.map((d, i) => `
    <div class="metric">
      <small>${d.label}</small>
      ${isEditable(i) ? `
        <div style="display: flex; align-items: center; gap: 2px;">
          <span style="font-size: 0.9rem; font-weight: 700;">£</span>
          <input type="number" id="revenue-input-${svgId}-${i}" class="no-spinner" step="any" value="${revenueUnit === 'm' ? Math.round((d.value / 1000) * 100) / 100 : Math.round(d.value)}" style="width: 80%; font: inherit; font-size: 0.9rem; font-weight: 700; padding: 2px; border: 1px solid var(--border); border-radius: 6px; text-align: right; color: var(--accent);">
          <span class="unit-suffix" style="font-size: 0.9rem; font-weight: 700;">${revenueUnit}</span>
        </div>
        ${i > 0 ? `<div id="yoy-text-${svgId}-${i}" style="font-size: 0.75rem; color: var(--accent); font-weight: 600;"></div>` : ''}
      ` : `
        <div style="display: flex; flex-direction: column; gap: 2px;">
          <strong id="revenue-text-${svgId}-${i}"></strong>
        </div>
      `}
    </div>
  `).join('');

  const revInputs = data.map((d, i) => isEditable(i) ? document.getElementById(`revenue-input-${svgId}-${i}`) : document.getElementById(`revenue-text-${svgId}-${i}`));

  data.forEach((d, i) => {
    if (!isEditable(i)) return;
    const inputEl = revInputs[i];
    if (!inputEl) return;
    inputEl.addEventListener('input', (e) => {
      const typed = Number(e.target.value);
      const val = revenueUnit === 'm' ? typed * 1000 : typed;
      data[i].value = val;
      update();
    });
  });

  function xForIndex(i) { return plot.left + i * xStep; }
  function yForValue(value) {
    const ratio = (value - minRevenue) / (maxRevenue - minRevenue);
    return plot.bottom - ratio * plot.height;
  }
  function valueForY(y) {
    const clampedY = Math.max(plot.top, Math.min(plot.bottom, y));
    const ratio = (plot.bottom - clampedY) / plot.height;
    return Math.round((minRevenue + ratio * (maxRevenue - minRevenue)) * 10) / 10;
  }
  function pointerY(event) {
    const rect = svg.getBoundingClientRect();
    const scaleY = svg.viewBox.baseVal.height / rect.height;
    return (event.clientY - rect.top) * scaleY;
  }
  function renderYAxis() {
    yLabelsGroup.innerHTML = '';
    gridGroup.innerHTML = '';
    const ticks = computeNiceTicks(minRevenue, maxRevenue, 4, 5);
    let maxLabelWidth = 0;
    ticks.forEach(tick => {
      const y = yForValue(tick);
      make('line', { x1: plot.left, y1: y, x2: plot.right, y2: y, class: 'grid-line' }, gridGroup);
      const label = make('text', { x: plot.left - 12, y: y + 4, 'text-anchor': 'end', class: 'label' }, yLabelsGroup);
      label.textContent = formatRevenueTick(tick);
      maxLabelWidth = Math.max(maxLabelWidth, label.getComputedTextLength());
    });
    if (yAxisTitle) {
      const titleGap = 14;
      const leftEdge = (plot.left - 12) - maxLabelWidth;
      const titleX = Math.max(10, Math.min(20, Math.round(leftEdge - titleGap)));
      yAxisTitle.setAttribute('x', titleX);
      yAxisTitle.setAttribute('transform', `rotate(-90 ${titleX} ${plotMidY})`);
    }
  }

  make('line', { x1: plot.left, y1: plot.top, x2: plot.left, y2: plot.bottom, class: 'axis' }, axesGroup);
  make('line', { x1: plot.left, y1: plot.bottom, x2: plot.right, y2: plot.bottom, class: 'axis' }, axesGroup);

  data.forEach((d, i) => {
    const x = xForIndex(i);
    make('line', { x1: x, y1: plot.bottom, x2: x, y2: plot.bottom + 6, class: 'axis' }, axesGroup);
    const txt = make('text', { x, y: plot.bottom + 24, 'text-anchor': 'middle', class: 'label' }, xLabelsGroup);
    txt.textContent = d.label;
    const g = make('g', {}, pointsGroup);
    const tag = make('g', { class: 'value-tag' }, g);
    const rect = make('rect', { width: 64, height: 26, x: x - 32, y: 0 }, tag);
    const text = make('text', { x, y: 17, 'text-anchor': 'middle' }, tag);
    const point = make('circle', {
      cx: x,
      cy: yForValue(d.value),
      r: 8.5,
      class: i === 0 ? 'point point-fixed' : 'point',
      tabindex: '0',
      'aria-label': i === 0 ? `${title} ${d.label} revenue (set via the field above the chart)` : `Drag ${title} ${d.label} revenue`
    }, g);
    point.dataset.index = i;
    pointElements.push(point);
    tagElements.push({ group: tag, rect, text });
  });


  function update() {
    renderYAxis();
    const coords = data.map((d, i) => [xForIndex(i), yForValue(d.value)]);
    const linePath = coords.map((p, i) => `${i === 0 ? 'M' : 'L'} ${p[0]} ${p[1]}`).join(' ');
    line.setAttribute('d', linePath);
    area.setAttribute('d', `${linePath} L ${coords[coords.length - 1][0]} ${plot.bottom} L ${coords[0][0]} ${plot.bottom} Z`);

    data.forEach((d, i) => {
      const x = xForIndex(i);
      const y = yForValue(d.value);
      pointElements[i].setAttribute('cx', x);
      pointElements[i].setAttribute('cy', y);
      const tag = tagElements[i];
      tag.group.setAttribute('transform', `translate(0, ${y - 38})`);
      tag.text.textContent = formatRevenueDisplay(d.value);
      const width = Math.max(64, tag.text.getComputedTextLength() + 22);
      const tagLeft = Math.max(plot.left + 6, x - width / 2);
      tag.rect.setAttribute('width', width);
      tag.rect.setAttribute('x', tagLeft);
      tag.text.setAttribute('x', tagLeft + width / 2);
    });

    data.forEach((d, i) => {
      if (isEditable(i)) {
        if (document.activeElement !== revInputs[i]) {
          revInputs[i].value = revenueUnit === 'm' ? Math.round((d.value / 1000) * 100) / 100 : Math.round(d.value);
        }
        if (i > 0) {
          const prevValue = data[i - 1].value;
          const growth = prevValue ? ((d.value - prevValue) / prevValue) * 100 : 0;
          const sign = growth > 0 ? '+' : '';
          const yoyEl = document.getElementById(`yoy-text-${svgId}-${i}`);
          if (yoyEl) {
            yoyEl.textContent = `${sign}${growth.toFixed(1)}% YoY`;
            yoyEl.style.color = growth < 0 ? '#d9534f' : 'var(--accent)';
          }
        }
      } else {
        revInputs[i].textContent = formatRevenueDisplay(d.value);
      }
    });

    if (onUpdate) onUpdate(data);
  }

  let activeIndex = null;
  function startDrag(event) {
    const target = event.target.closest('.point');
    if (!target || target.classList.contains('point-fixed')) return;
    activeIndex = Number(target.dataset.index);
    target.classList.add('active');
  }
  function moveDrag(event) {
    if (activeIndex === null) return;
    const val = valueForY(pointerY(event));
    data[activeIndex].value = val;
    update();
  }
  function endDrag() {
    if (activeIndex === null) return;
    pointElements[activeIndex].classList.remove('active');
    activeIndex = null;
  }
  svg.addEventListener('pointerdown', (event) => {
    startDrag(event);
    if (activeIndex !== null) svg.setPointerCapture(event.pointerId);
  });
  svg.addEventListener('pointermove', moveDrag);
  svg.addEventListener('pointerup', (event) => {
    endDrag();
    if (svg.hasPointerCapture(event.pointerId)) svg.releasePointerCapture(event.pointerId);
  });
  svg.addEventListener('pointercancel', endDrag);
  svg.addEventListener('pointerleave', endDrag);
  update();

  return {
    getData: () => data.map(item => ({ ...item })),
    setDataValue: (idx, val) => {
      if (idx === 0) {
        data.forEach(d => d.value = val);
      } else {
        data[idx].value = val;
      }
      update();
    },
    setYRange: (min, max) => {
      minRevenue = min;
      maxRevenue = max;
      update();
    },
    refresh: update,
    setValues: (newValues) => {
      newValues.forEach((val, i) => {
        data[i].value = val;
      });
      update();
    },
    updateLabels: (newLabels) => {
      data.forEach((d, i) => {
        d.label = newLabels[i];
      });
      const txtElements = svg.querySelectorAll('.x-labels text');
      txtElements.forEach((txt, i) => {
        if (newLabels[i]) txt.textContent = newLabels[i];
      });
      const legendItems = summary.querySelectorAll('.metric small');
      legendItems.forEach((small, i) => {
        if (newLabels[i]) small.textContent = newLabels[i];
      });
      update();
    }
  };
}

function applyYoYGrowth(scenarioKey, percent) {
  const scenario = scenarioKey === 's1' ? scenario1 : scenario2;
  const currentData = scenario.getData();
  const baseline = currentData[0].value;
  const newValues = [baseline];

  for (let i = 1; i < currentData.length; i++) {
    const prevValue = newValues[i - 1];
    newValues.push(prevValue * (1 + percent / 100));
  }

  scenario.setValues(newValues);
}

function applyCustomYoY(scenarioKey) {
  const input = document.getElementById(`custom-yoy-input-${scenarioKey}`);
  if (input && input.value !== '') {
    const val = Number(input.value);
    applyYoYGrowth(scenarioKey, val);
  }
}

// Baseline P&L shared by both scenarios (client figures). Net profit is after depreciation.
let baselineNetProfitK = DEFAULT_BASELINE_REVENUE_K * DEFAULT_BASELINE_MARGIN_PCT / 100;

function getBaseline() {
  return {
    employees: Math.max(0, Number(document.getElementById('emp1-baseline')?.value) || 0),
    // Entered in £; the model works in £k
    payroll: Math.max(0, parseMoneyInput(document.getElementById('emp1-cost'))) / 1000,
    netProfit: baselineNetProfitK
  };
}

// Non-labour cost saving for each year, in % points of turnover (+ = saving). The engine uses cost
// change (+ = cost up), so the sign flips here.
function getNonLabourSavingPct(scenarioKey) {
  return [0, ...[1, 2, 3].map(y => Number(document.getElementById(`${scenarioKey}-nonlabour-y${y}`)?.value) || 0)];
}

// Productivity target for each year, % vs baseline productivity ([baseline, Y1, Y2, Y3])
function getProductivityTargetPct(scenarioKey) {
  return [0, ...[1, 2, 3].map(y => Number(document.getElementById(`${scenarioKey}-productivity-y${y}`)?.value) || 0)];
}

// Story inputs are read from the page so they reset and export like every other field
function getStory(scenarioKey) {
  const savingPct = getNonLabourSavingPct(scenarioKey);
  return {
    productivityPathPct: getProductivityTargetPct(scenarioKey),
    nonLabourDrivers: [{ name: 'Non-labour cost saving', pathPp: savingPct.map(v => -v) }],
    manualHeadcount: !!document.getElementById(`${scenarioKey}-manual-headcount`)?.checked
  };
}

function formatSigned(value, decimals) {
  const rounded = Number(value.toFixed(decimals));
  return `${rounded > 0 ? '+' : ''}${(rounded === 0 ? 0 : rounded).toFixed(decimals)}`;
}

function scenarioIds(scenarioKey) {
  return scenarioKey === 's1'
    ? { prefix: 'emp1', containerId: 'profitGrid1', chart: scenario1 }
    : { prefix: 'emp2', containerId: 'profitGrid2', chart: scenario2 };
}

function renderProfitPanel(scenarioKey) {
  const { containerId } = scenarioIds(scenarioKey);
  const container = document.getElementById(containerId);
  const years = ['Baseline', String(yr1), String(yr2), String(yr3)];

  container.innerHTML = years.map((year, i) => `
    <div class="profit-row">
      <div class="profit-head">
        <div class="profit-label${i === 0 ? ' profit-label-wide' : ''}"><span class="profit-year">${year}</span> net profit value:
          ${(i === 0 && scenarioKey === 's1') ? `
            <span style="display: inline-flex; align-items: center; gap: 2px; vertical-align: middle; max-width: 100%;">
              <span>£</span>
              <input type="text" inputmode="text" autocomplete="off" id="${containerId}-amount-input-0" style="width: 110px; min-width: 60px; max-width: 100%; text-align: right; border: 1px solid var(--border); border-radius: 6px; padding: 2px 4px; font-size: 0.92rem; font-family: inherit;">
            </span>
          ` : `<span id="${containerId}-value-${i}"></span>`}
        </div>
        ${i === 0 ? '' : `
          <div class="profit-badges">
            <span class="profit-nonlabour" id="${containerId}-productivity-${i}"></span>
            <span class="profit-nonlabour" id="${containerId}-nonlabour-${i}"></span>
          </div>
        `}
        <span class="profit-percent" id="${containerId}-percent-${i}"></span>
      </div>
    </div>
  `).join('');

  const amountInput = document.getElementById(`${containerId}-amount-input-0`);
  if (amountInput) {
    // Formatting runs first so the recalculation reads the tidied value
    attachMoneyFormatting(amountInput);
    amountInput.addEventListener('input', () => {
      // Entered in £; the model works in £k
      baselineNetProfitK = parseMoneyInput(amountInput) / 1000;
      recalcAll();
    });
  }
}

// Last headcounts shown, used to cascade manual edits to later years
const lastEmployeeCounts = { emp1: [0, 0, 0, 0], emp2: [0, 0, 0, 0] };

function recalcScenario(scenarioKey) {
  const { prefix, containerId, chart } = scenarioIds(scenarioKey);
  if (!chart) return;

  const story = getStory(scenarioKey);
  const base = getBaseline();
  const yearInputs = [1, 2, 3].map(i => document.getElementById(`${prefix}-y${i}`));

  const pnl = computeScenarioPnl({
    revenues: chart.getData().map(d => d.value),
    baseEmployees: base.employees,
    basePayroll: base.payroll,
    baseNetProfit: base.netProfit,
    productivityPathPct: story.productivityPathPct,
    nonLabourDrivers: story.nonLabourDrivers,
    manualEmployees: story.manualHeadcount
      ? [base.employees, ...yearInputs.map(el => Number(el?.value) || 0)]
      : null
  });

  employeeCount[scenarioKey] = pnl.map(p => p.employees);
  employeeCostK[scenarioKey] = pnl.map(p => p.payroll);
  netProfitK[scenarioKey] = pnl.map(p => p.netProfit);
  lastEmployeeCounts[prefix] = pnl.map(p => p.employees);

  // Headcount is calculated from the productivity target unless manual headcount is ticked
  yearInputs.forEach((el, idx) => {
    if (!el) return;
    el.disabled = !story.manualHeadcount;
    if (!story.manualHeadcount) el.value = pnl[idx + 1].employees;
  });

  // With manual headcount the targets drive nothing, so the boxes are greyed out and show the
  // productivity the entered headcount gives. Unticking keeps those figures as the new targets.
  [1, 2, 3].forEach(y => {
    const el = document.getElementById(`${scenarioKey}-productivity-y${y}`);
    if (!el) return;
    el.disabled = story.manualHeadcount;
    if (story.manualHeadcount) el.value = Number(pnl[y].productivityPct.toFixed(1));
  });

  const amountInput = document.getElementById(`${containerId}-amount-input-0`);
  if (amountInput && document.activeElement !== amountInput) {
    amountInput.value = formatMoneyValue(base.netProfit * 1000);
  }

  pnl.forEach((p, i) => {
    const valueSpan = document.getElementById(`${containerId}-value-${i}`);
    if (valueSpan) valueSpan.textContent = formatCurrencyK(p.netProfit);
    const percentSpan = document.getElementById(`${containerId}-percent-${i}`);
    if (percentSpan) percentSpan.textContent = `${p.netMarginPct.toFixed(2)}%`;

    const productivitySpan = document.getElementById(`${containerId}-productivity-${i}`);
    if (productivitySpan) {
      productivitySpan.textContent = `${formatSigned(p.productivityPct, 1)}% productivity`;
      productivitySpan.dataset.trend = p.productivityPct > 0.05 ? 'up' : (p.productivityPct < -0.05 ? 'down' : 'flat');
      productivitySpan.title = story.manualHeadcount
        ? `Turnover per employee: ${formatCurrencyK(p.productivity)} in ${baseYear + i} vs ${formatCurrencyK(pnl[0].productivity)} in ${baseYear}. Headcount ${p.employees} (entered manually).`
        : `Target: ${formatSigned(p.targetProductivityPct, 1)}%. Turnover per employee: ${formatCurrencyK(p.productivity)} in ${baseYear + i} (target ${formatCurrencyK(p.targetProductivity)}) vs ${formatCurrencyK(pnl[0].productivity)} in ${baseYear}. Headcount ${p.employees} (exact headcount for the target: ${p.targetEmployees.toFixed(2)}).`;
    }

    const nonLabourSpan = document.getElementById(`${containerId}-nonlabour-${i}`);
    if (nonLabourSpan) {
      // Shown as a saving: a fall in the non-labour cost share is a positive, green figure.
      // % points of turnover, so it adds straight onto the net profit %
      const savingPp = -p.nonLabourChangePp;
      nonLabourSpan.textContent = `${formatSigned(savingPp, 2)} pts non-labour saving`;
      nonLabourSpan.dataset.trend = savingPp > 0.005 ? 'up' : (savingPp < -0.005 ? 'down' : 'flat');
      nonLabourSpan.title = `Non-labour cost saving: ${formatCurrencyK(-p.nonLabourChange)} (${formatSigned(savingPp, 2)} % points of turnover). Non-labour costs: ${formatCurrencyK(p.nonLabour)} (${p.nonLabourPct.toFixed(2)}% of turnover) vs ${pnl[0].nonLabourPct.toFixed(2)}% in ${baseYear}. Covers materials, plant hire and indirect costs.`;
    }
  });

  // £ value of each year's non-labour cost saving, under its input (negative = cost increase)
  [1, 2, 3].forEach(y => {
    const gbp = document.getElementById(`${scenarioKey}-nonlabour-gbp-y${y}`);
    if (gbp) gbp.textContent = formatCurrencyK(-pnl[y].nonLabourChange);
  });

  if (scenarioKey === 's1') {
    const metric = document.getElementById('emp1-metric');
    const averageCost = base.employees > 0 ? base.payroll / base.employees : 0;
    if (metric) metric.innerHTML = `Average cost per employee: <strong>${formatCurrencyK(averageCost)}</strong>`;
  } else {
    // Scenario 2 baseline mirrors Scenario 1
    const emp2Base = document.getElementById('emp2-baseline');
    const emp2Cost = document.getElementById('emp2-cost');
    if (emp2Base) emp2Base.value = base.employees;
    if (emp2Cost) emp2Cost.value = formatMoneyValue(base.payroll * 1000);

    let newJobsTotal = 0;
    for (let i = 1; i <= 3; i++) {
      const newJobs = Math.max(0, pnl[i].employees - pnl[i - 1].employees);
      newJobsTotal += newJobs;
      const el = document.getElementById(`forecast-new-y${i}`);
      if (el) el.textContent = newJobs;
    }
    const totalEl = document.getElementById('forecast-new-total');
    if (totalEl) totalEl.textContent = newJobsTotal;
  }

  updateSummaryTable();
}

function recalcAll() {
  recalcScenario('s1');
  recalcScenario('s2');
}

// Manual headcount: changing a year moves later years by the same amount
function handleEmployeeYearInput(prefix, yearIdx) {
  const scenarioKey = prefix === 'emp1' ? 's1' : 's2';
  const input = document.getElementById(`${prefix}-y${yearIdx}`);
  const delta = (Number(input.value) || 0) - lastEmployeeCounts[prefix][yearIdx];
  if (delta !== 0) {
    for (let j = yearIdx + 1; j <= 3; j++) {
      const later = document.getElementById(`${prefix}-y${j}`);
      if (later) later.value = Math.max(0, (Number(later.value) || 0) + delta);
    }
  }
  recalcScenario(scenarioKey);
}

// A baseline headcount change moves manual forecast headcounts by the same amount
function handleBaselineEmployeesInput() {
  const newBase = Math.max(0, Number(document.getElementById('emp1-baseline').value) || 0);
  ['emp1', 'emp2'].forEach(prefix => {
    const scenarioKey = prefix === 'emp1' ? 's1' : 's2';
    if (!getStory(scenarioKey).manualHeadcount) return;
    const delta = newBase - lastEmployeeCounts[prefix][0];
    if (delta === 0) return;
    for (let j = 1; j <= 3; j++) {
      const el = document.getElementById(`${prefix}-y${j}`);
      if (el) el.value = Math.max(0, (Number(el.value) || 0) + delta);
    }
  });
  recalcAll();
}

function updateUpskilledTotal() {
  let total = 0;
  for (let idx = 1; idx <= 3; idx++) {
    total += Math.max(0, parseInt(document.getElementById(`upskilled-y${idx}`)?.value) || 0);
  }
  const totalEl = document.getElementById('upskilled-total');
  if (totalEl) totalEl.textContent = total;
}

// Scenario 2 salary bands are switched off until the core engine is validated.
// The band costing (removed in this version; see git history before v4.0) was:
//   payroll_t = baseline payroll + sum of new jobs by band to date x band salary
//   BAND_SALARIES = [15, 20.4, 30, 40, 50, 65] (£k)

// Set initial baseline
function syncChartScales(baseline) {
  if (!scenario1 || !scenario2) return;
  const min = Math.max(0, baseline * 0.6);
  const max = baseline * 3;
  scenario1.setYRange(min, max);
  scenario2.setYRange(min, max);
}

function syncEmpBaseline(e, targetId) {
  const target = document.getElementById(targetId);
  if (target.value !== e.target.value) {
    target.value = e.target.value;
    target.dispatchEvent(new Event('input'));
  }
}

