// Side panel shows Summary, Comparison or nothing ('none')
let sidePanel = 'summary';

function applySidePanel(panel) {
  sidePanel = panel;
  const wrapper = document.querySelector('.layout-wrapper');
  if (wrapper) wrapper.classList.toggle('sidebar-collapsed', panel === 'none');
  ['summary', 'comparison'].forEach(name => {
    document.getElementById(`panel-toggle-${name}`)?.classList.toggle('active', panel === name);
    const section = document.getElementById(`side-panel-${name}`);
    // Keep the last section visible while the panel slides closed
    if (section && panel !== 'none') section.hidden = panel !== name;
  });
  try { sessionStorage.setItem('gva_side_panel', panel); } catch (e) { }
  window.dispatchEvent(new Event('resize'));
}

// Settings menu (three-line button): Edit Baseline, Import, Export, Sign Out
function setSettingsMenuOpen(open) {
  const list = document.getElementById('settings-menu-list');
  const btn = document.getElementById('settings-menu-btn');
  if (!list || !btn) return;
  list.hidden = !open;
  btn.setAttribute('aria-expanded', String(open));
  btn.classList.toggle('active', open);
}

function toggleSettingsMenu() {
  setSettingsMenuOpen(document.getElementById('settings-menu-list')?.hidden);
}

// Close on outside click, Escape, or after choosing an item
document.addEventListener('click', e => {
  const menu = document.getElementById('settings-menu');
  if (!menu) return;
  if (!menu.contains(e.target) || e.target.closest('[role="menuitem"]')) setSettingsMenuOpen(false);
});
document.addEventListener('keydown', e => {
  if (e.key === 'Escape') setSettingsMenuOpen(false);
});

// Clicking the highlighted option again hides the panel
function selectSidePanel(panel) {
  applySidePanel(sidePanel === panel ? 'none' : panel);
}

// Standalone Modal Functions
function showBaselineModal() {
  document.getElementById('modal-revenue').value = Number((scenario1.getData()[0].value / 1000).toFixed(4));
  document.getElementById('modal-profit').value = formatMoneyValue(baselineNetProfitK * 1000);
  document.getElementById('modal-emp-count').value = document.getElementById('emp1-baseline').value;
  document.getElementById('modal-emp-cost').value = formatMoneyValue(parseMoneyInput(document.getElementById('emp1-cost')));
  // Depreciation and project cost are edited here or in the Depreciation section; both show the same values
  document.getElementById('modal-depreciation').value = formatMoneyValue(parseMoneyInput(document.getElementById('dep-baseline')));
  document.getElementById('modal-project-cost').value = formatMoneyValue(parseMoneyInput(document.getElementById('project-cost-input')));
  document.getElementById('baselineModal').classList.add('active');
  if (typeof validateBaselineModalInputs === 'function') {
    validateBaselineModalInputs();
  }
}

function highlightIfInvalid(el, isInvalid) {
  if (!el) return;
  if (isInvalid) {
    el.style.backgroundColor = 'rgba(217, 83, 79, 0.08)';
    el.style.borderColor = '#d9534f';
    el.style.color = '#d9534f';
  } else {
    el.style.backgroundColor = '';
    el.style.borderColor = '';
    el.style.color = '';
  }
}

function highlightCellIfInvalid(el, isInvalid) {
  if (!el) return;
  if (isInvalid) {
    el.style.color = '#d9534f';
    el.style.backgroundColor = 'rgba(217, 83, 79, 0.08)';
    el.style.fontWeight = '700';
  } else {
    el.style.color = '';
    el.style.backgroundColor = '';
    el.style.fontWeight = '';
  }
}

function validateBaselineModalInputs() {
  const rev = (Number(document.getElementById('modal-revenue')?.value) || 0) * 1000;
  // Profit and salary cost are entered in £; compare in £k
  const profit = parseMoneyInput(document.getElementById('modal-profit')) / 1000;
  const empCost = parseMoneyInput(document.getElementById('modal-emp-cost')) / 1000;

  const isEmpCostHigher = empCost > rev;
  const isProfitTooHigh = profit > (rev - empCost);

  highlightIfInvalid(document.getElementById('modal-revenue'), isEmpCostHigher);
  highlightIfInvalid(document.getElementById('modal-profit'), isEmpCostHigher || isProfitTooHigh);
  highlightIfInvalid(document.getElementById('modal-emp-cost'), isEmpCostHigher);
}

function hideBaselineModal() {
  document.getElementById('baselineModal').classList.remove('active');
}

function handleApplyBaseline() {
  const rev = Number(document.getElementById('modal-revenue').value) * 1000;
  const profitVal = parseMoneyInput(document.getElementById('modal-profit'));
  const count = Number(document.getElementById('modal-emp-count').value);
  const cost = parseMoneyInput(document.getElementById('modal-emp-cost'));

  document.getElementById('emp1-baseline').value = count;
  document.getElementById('emp1-cost').value = formatMoneyValue(cost);
  baselineNetProfitK = profitVal / 1000;
  document.getElementById('dep-baseline').value = formatMoneyValue(parseMoneyInput(document.getElementById('modal-depreciation')));
  document.getElementById('project-cost-input').value = formatMoneyValue(parseMoneyInput(document.getElementById('modal-project-cost')));
  // A new baseline starts both scenarios on calculated headcount
  ['s1', 's2'].forEach(key => {
    const manual = document.getElementById(`${key}-manual-headcount`);
    if (manual) manual.checked = false;
  });

  scenario1.setDataValue(0, rev);
  applyYoYGrowth('s1', DEFAULT_YOY_GROWTH_PCT.s1);
  applyYoYGrowth('s2', DEFAULT_YOY_GROWTH_PCT.s2);
  recalcAll();

  hideBaselineModal();
}

function handleSkipBaseline() {
  hideBaselineModal();
}

function showComparisonModal() {
  document.getElementById('comparisonModal').classList.add('active');
  runComparisonSanityChecks();
}

function hideComparisonModal() {
  document.getElementById('comparisonModal').classList.remove('active');
}

function showInfoModal() {
  document.getElementById('infoModal').classList.add('active');
}

function hideInfoModal() {
  document.getElementById('infoModal').classList.remove('active');
}

function runComparisonSanityChecks() {
  const getValue = (id) => {
    const el = document.getElementById(id);
    return el && el.value !== '' ? Number(el.value) : 0;
  };

  const getElement = (id) => document.getElementById(id);

  // Get headcount baselines from main dashboard
  const emp1Baseline = Math.max(1, Number(getElement('emp1-baseline')?.value) || 50);
  const emp2Baseline = Math.max(1, Number(getElement('emp2-baseline')?.value) || 50);

  // Get baseline annual employee costs from comparison table
  const s1EmpBaselineCost = getValue('comp-s1-emp-baseline');
  const s2EmpBaselineCost = getValue('comp-s2-emp-baseline');

  // 1. Calculate per-employee cost
  const s1PerEmployeeCost = s1EmpBaselineCost / emp1Baseline;
  const s2PerEmployeeCost = s2EmpBaselineCost / emp2Baseline;

  // Format helper
  const formatSalary = (valK) => {
    const full = Math.round(valK * 1000);
    return '£' + full.toLocaleString();
  };

  const s1CostValEl = getElement('sanity-val-s1-emp-cost');
  const s1FormulaEl = getElement('sanity-formula-s1-emp-cost');
  const s2CostValEl = getElement('sanity-val-s2-emp-cost');
  const s2FormulaEl = getElement('sanity-formula-s2-emp-cost');

  if (s1CostValEl) s1CostValEl.textContent = formatSalary(s1PerEmployeeCost);
  if (s1FormulaEl) s1FormulaEl.textContent = `£${s1EmpBaselineCost.toLocaleString()}k / ${emp1Baseline} employees`;
  if (s2CostValEl) s2CostValEl.textContent = formatSalary(s2PerEmployeeCost);
  if (s2FormulaEl) s2FormulaEl.textContent = `£${s2EmpBaselineCost.toLocaleString()}k / ${emp2Baseline} employees`;

  let warningsCount = 0;
  let criticalErrorsCount = 0;

  // Evaluate Per-Employee Cost Check
  const badgeEmpCost = getElement('sanity-badge-emp-cost');
  const alertEmpCost = getElement('sanity-alert-emp-cost');
  let empCostStatus = 'Healthy';
  let empCostAlertText = '';

  // Typical salary range: £10k to £150k
  const s1RevBaseline = scenario1 ? scenario1.getData()[0].value : 4500;
  const s2RevBaseline = scenario2 ? scenario2.getData()[0].value : 4500;

  if (s1PerEmployeeCost <= 0 || s2PerEmployeeCost <= 0) {
    empCostStatus = 'Error';
    empCostAlertText = 'Warning: Baseline cost or employee count is zero or negative. Please enter valid values.';
    criticalErrorsCount++;
  } else if (s1EmpBaselineCost > s1RevBaseline || s2EmpBaselineCost > s2RevBaseline) {
    empCostStatus = 'Error';
    empCostAlertText = 'Warning: Baseline annual employee cost is higher than turnover.';
    criticalErrorsCount++;
  } else if (s1PerEmployeeCost < 12 || s2PerEmployeeCost < 12) {
    empCostStatus = 'Caution';
    empCostAlertText = `Warning: Calculated annual average salary (${formatSalary(Math.min(s1PerEmployeeCost, s2PerEmployeeCost))}) is unusually low (below £12k). Verify that costs are entered in thousands (£k).`;
    warningsCount++;
  } else if (s1PerEmployeeCost > 150 || s2PerEmployeeCost > 150) {
    empCostStatus = 'Caution';
    empCostAlertText = `Warning: Calculated annual average salary (${formatSalary(Math.max(s1PerEmployeeCost, s2PerEmployeeCost))}) is unusually high (above £150k). Verify headcount or costs.`;
    warningsCount++;
  }

  if (badgeEmpCost) {
    badgeEmpCost.textContent = empCostStatus;
    badgeEmpCost.style.background = empCostStatus === 'Healthy' ? '#dff2ef' : (empCostStatus === 'Caution' ? '#fef3c7' : '#fee2e2');
    badgeEmpCost.style.color = empCostStatus === 'Healthy' ? '#0b4e53' : (empCostStatus === 'Caution' ? '#b45309' : '#b91c1c');
  }
  if (alertEmpCost) {
    if (empCostAlertText) {
      alertEmpCost.innerHTML = empCostAlertText;
      alertEmpCost.style.display = 'block';
    } else {
      alertEmpCost.style.display = 'none';
    }
  }

  // 2. Baseline Alignment Check
  const s1ProfBaseline = getValue('comp-s1-prof-baseline');
  const s2ProfBaseline = getValue('comp-s2-prof-baseline');

  // Main dashboard cost is entered in £; the comparison table is in £k
  const mainEmpCostBase = parseMoneyInput(getElement('emp1-cost')) / 1000;

  const badgeAlignment = getElement('sanity-badge-alignment');
  const alertAlignment = getElement('sanity-alert-alignment');
  const valAlignmentCost = getElement('sanity-val-alignment-cost');
  const valAlignmentProfit = getElement('sanity-val-alignment-profit');

  let alignmentStatus = 'Healthy';
  let alignmentAlertText = [];

  // Check if Scenario 1 matches Scenario 2 in baselines
  if (s1EmpBaselineCost !== s2EmpBaselineCost) {
    alignmentAlertText.push(`Scenario 1 and Scenario 2 baseline employee costs differ (£${s1EmpBaselineCost}k vs £${s2EmpBaselineCost}k).`);
    alignmentStatus = 'Caution';
  }
  if (s1ProfBaseline !== s2ProfBaseline) {
    alignmentAlertText.push(`Scenario 1 and Scenario 2 baseline net profits differ (£${s1ProfBaseline}k vs £${s2ProfBaseline}k).`);
    alignmentStatus = 'Caution';
  }

  // Check if comparison table matches main dashboard
  if (s1EmpBaselineCost !== mainEmpCostBase) {
    alignmentAlertText.push(`Comparison baseline employee cost (£${s1EmpBaselineCost}k) differs from Main dashboard baseline (£${mainEmpCostBase}k).`);
    alignmentStatus = 'Caution';
  }

  if (valAlignmentCost) {
    valAlignmentCost.textContent = (s1EmpBaselineCost === s2EmpBaselineCost && s1EmpBaselineCost === mainEmpCostBase)
      ? 'Perfect Match'
      : `${s1EmpBaselineCost === s2EmpBaselineCost ? 'S1=S2' : 'S1≠S2'} (Main: £${mainEmpCostBase}k)`;
    valAlignmentCost.style.color = (s1EmpBaselineCost === s2EmpBaselineCost && s1EmpBaselineCost === mainEmpCostBase) ? 'var(--accent)' : '#b45309';
  }

  if (valAlignmentProfit) {
    valAlignmentProfit.textContent = (s1ProfBaseline === s2ProfBaseline) ? 'S1/S2 Aligned' : `Mismatched (S1: £${s1ProfBaseline}k, S2: £${s2ProfBaseline}k)`;
    valAlignmentProfit.style.color = (s1ProfBaseline === s2ProfBaseline) ? 'var(--accent)' : '#b45309';
  }

  if (alignmentStatus === 'Caution') warningsCount++;

  if (badgeAlignment) {
    badgeAlignment.textContent = alignmentStatus;
    badgeAlignment.style.background = alignmentStatus === 'Healthy' ? '#dff2ef' : '#fef3c7';
    badgeAlignment.style.color = alignmentStatus === 'Healthy' ? '#0b4e53' : '#b45309';
  }
  if (alertAlignment) {
    if (alignmentAlertText.length > 0) {
      alertAlignment.innerHTML = 'Warning: ' + alignmentAlertText.join('<br>');
      alertAlignment.style.display = 'block';
    } else {
      alertAlignment.style.display = 'none';
    }
  }

  // 3. Profit Margin Check
  const badgeProfit = getElement('sanity-badge-profit');
  const alertProfit = getElement('sanity-alert-profit');
  const s1MarginEl = getElement('sanity-val-s1-margin');
  const s2MarginEl = getElement('sanity-val-s2-margin');

  const s1RevBaselineVal = scenario1 ? scenario1.getData()[0].value : 4500;
  const s2RevBaselineVal = scenario2 ? scenario2.getData()[0].value : 4500;

  const s1Margin = s1RevBaselineVal ? (s1ProfBaseline / s1RevBaselineVal) * 100 : 0;
  const s2Margin = s2RevBaselineVal ? (s2ProfBaseline / s2RevBaselineVal) * 100 : 0;

  if (s1MarginEl) s1MarginEl.textContent = `${s1Margin.toFixed(1)}%`;
  if (s2MarginEl) s2MarginEl.textContent = `${s2Margin.toFixed(1)}%`;

  let profitStatus = 'Healthy';
  let profitAlertText = '';

  if (s1Margin < 0 || s2Margin < 0) {
    profitStatus = 'Caution';
    profitAlertText = 'Warning: Implied net profit margin is negative. Verify profit/loss values.';
    warningsCount++;
  } else if (s1Margin > 80 || s2Margin > 80) {
    profitStatus = 'Error';
    profitAlertText = 'Warning: Net profit exceeds 80% of revenue. Verify turnover and profit values.';
    criticalErrorsCount++;
  } else if (s1ProfBaseline > (s1RevBaselineVal - s1EmpBaselineCost) || s2ProfBaseline > (s2RevBaselineVal - s2EmpBaselineCost)) {
    profitStatus = 'Error';
    profitAlertText = 'Warning: Net profit cannot be greater than the difference between turnover and employee cost.';
    criticalErrorsCount++;
  } else if (s1Margin > 50 || s2Margin > 50) {
    profitStatus = 'Caution';
    profitAlertText = 'Warning: Net profit margin is exceptionally high (above 50%). Verify numbers.';
    warningsCount++;
  }

  if (badgeProfit) {
    badgeProfit.textContent = profitStatus;
    badgeProfit.style.background = profitStatus === 'Healthy' ? '#dff2ef' : (profitStatus === 'Caution' ? '#fef3c7' : '#fee2e2');
    badgeProfit.style.color = profitStatus === 'Healthy' ? '#0b4e53' : (profitStatus === 'Caution' ? '#b45309' : '#b91c1c');
  }
  if (alertProfit) {
    if (profitAlertText) {
      alertProfit.innerHTML = profitAlertText;
      alertProfit.style.display = 'block';
    } else {
      alertProfit.style.display = 'none';
    }
  }

  // 4. GVA & ROI Validation
  const badgeRoi = getElement('sanity-badge-roi');
  const alertRoi = getElement('sanity-alert-roi');
  const totalGvaEl = getElement('sanity-val-total-gva');
  const roiMultEl = getElement('sanity-val-roi-mult');

  const compTotalGva = getValue('comp-total-gva');
  const compProjCost = getValue('comp-project-cost') || 0;
  const roiMultiplier = compProjCost > 0 ? (compTotalGva / compProjCost) : 0;

  if (totalGvaEl) {
    const fullGva = Math.round(compTotalGva * 1000);
    totalGvaEl.textContent = (fullGva < 0 ? '-' : '') + '£' + Math.abs(fullGva).toLocaleString();
  }
  if (roiMultEl) roiMultEl.textContent = compProjCost > 0 ? `${roiMultiplier.toFixed(1)}x` : 'N/A (Cost = 0)';

  let roiStatus = 'Healthy';
  let roiAlertText = '';

  if (compTotalGva < 0) {
    roiStatus = 'Error';
    roiAlertText = 'Warning: Total GVA gain is negative. The intervention under Scenario 2 is generating less GVA than Scenario 1.';
    criticalErrorsCount++;
  } else if (compProjCost > 0 && roiMultiplier < 1) {
    roiStatus = 'Caution';
    roiAlertText = 'Warning: Implied ROI is less than 1.0x. GVA gains do not fully cover the estimated project cost.';
    warningsCount++;
  }

  if (badgeRoi) {
    badgeRoi.textContent = roiStatus;
    badgeRoi.style.background = roiStatus === 'Healthy' ? '#dff2ef' : (roiStatus === 'Caution' ? '#fef3c7' : '#fee2e2');
    badgeRoi.style.color = roiStatus === 'Healthy' ? '#0b4e53' : (roiStatus === 'Caution' ? '#b45309' : '#b91c1c');
  }
  if (alertRoi) {
    if (roiAlertText) {
      alertRoi.innerHTML = roiAlertText;
      alertRoi.style.display = 'block';
    } else {
      alertRoi.style.display = 'none';
    }
  }

  // Update Summary Banner
  const summaryBanner = getElement('sanity-summary-banner');
  if (summaryBanner) {
    if (criticalErrorsCount > 0) {
      summaryBanner.style.background = '#fee2e2';
      summaryBanner.style.color = '#991b1b';
      summaryBanner.innerHTML = `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><octagon points="7.86 2 16.14 2 22 7.86 22 16.14 16.14 22 7.86 22 2 16.14 2 7.86 7.86 2"></octagon><line x1="12" y1="8" x2="12" y2="12"></line><line x1="12" y1="16" x2="12.01" y2="16"></line></svg>` +
        ` Checks Failed: ${criticalErrorsCount} error(s), ${warningsCount} warning(s)`;
    } else if (warningsCount > 0) {
      summaryBanner.style.background = '#fef3c7';
      summaryBanner.style.color = '#92400e';
      summaryBanner.innerHTML = `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"></path><line x1="12" y1="9" x2="12" y2="13"></line><line x1="12" y1="17" x2="12.01" y2="17"></line></svg>` +
        ` ${warningsCount} warning(s) detected`;
    } else {
      summaryBanner.style.background = '#d1fae5';
      summaryBanner.style.color = '#065f46';
      summaryBanner.innerHTML = `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"></path><polyline points="22 4 12 14.01 9 11.01"></polyline></svg>` +
        ` All checks passed`;
    }
  }
}

/// Excel import and export in the GVA grant-form layout (see GVA_workbook.js and "GVA Model Template.xlsx")
const XLSX_MIME = 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';

function getModelDetails() {
  return {
    company: document.getElementById('model-company')?.value.trim() || '',
    version: document.getElementById('model-version')?.value.trim() || ''
  };
}

function collectWorkbookModel() {
  recalcAll();
  const base = getBaseline();
  const { company, version } = getModelDetails();
  const story = { s1: getStory('s1'), s2: getStory('s2') };
  const revenuesK = { s1: scenario1.getData().map(d => d.value), s2: scenario2.getData().map(d => d.value) };
  // The workbook takes NPBT % as an input, so it gets the app's calculated net margin
  const netMarginPct = key => netProfitK[key].map((np, i) => (revenuesK[key][i] ? (np / revenuesK[key][i]) * 100 : 0));
  return {
    company,
    version,
    revenuesK,
    employees: { s1: employeeCount.s1.slice(), s2: employeeCount.s2.slice() },
    basePayrollK: base.payroll,
    baseNetProfitK: base.netProfit,
    netMarginPct: { s1: netMarginPct('s1'), s2: netMarginPct('s2') },
    productivityTargetPct: { s1: story.s1.productivityPathPct, s2: story.s2.productivityPathPct },
    // The workbook keeps a depreciation cell per year; each gets the baseline figure
    depreciation: [1, 2, 3].map(() => getBaselineDepreciationK() * 1000),
    projectCost: getProjectCostK() * 1000
  };
}

async function handleExport() {
  try {
    const model = collectWorkbookModel();
    const wb = await writeGvaWorkbook(ExcelJS, GVA_TEMPLATE_BASE64, model);
    const buffer = await wb.xlsx.writeBuffer();
    const url = URL.createObjectURL(new Blob([buffer], { type: XLSX_MIME }));
    const link = document.createElement('a');
    link.href = url;
    link.download = gvaFileName(model.company, model.version);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  } catch (err) {
    console.error(err);
    alert('Export failed: ' + err.message);
  }
}

function handleImportClick() {
  document.getElementById('import-file-input').click();
}

// Headcount is "calculated" when the workbook's FTEs are what the productivity target gives;
// otherwise someone has set them by hand, so they come in as manual headcount
function isManualHeadcount(model, key) {
  const auto = computeScenarioPnl({
    revenues: model.revenuesK[key],
    baseEmployees: model.employees.s1[0],
    basePayroll: model.basePayrollK,
    baseNetProfit: model.baseNetProfitK,
    productivityPathPct: model.productivityTargetPct[key]
  });
  return [1, 2, 3].some(i => auto[i].employees !== model.employees[key][i]);
}

function applyWorkbookModel(model) {
  const setValue = (id, value) => {
    const el = document.getElementById(id);
    if (el) el.value = value;
  };
  const round = (n, dp) => Number(Number(n).toFixed(dp));

  setValue('model-company', model.company);
  setValue('model-version', model.version || '1.0');
  setValue('emp1-baseline', model.employees.s1[0]);
  setValue('emp1-cost', formatMoneyValue(model.basePayrollK * 1000));
  baselineNetProfitK = model.baseNetProfitK;
  // Depreciation is one baseline figure for every year; the workbook's Year 1 is used
  setValue('dep-baseline', formatMoneyValue(model.depreciation[0]));
  [1, 2, 3].forEach(i => {
    setValue(`emp1-y${i}`, model.employees.s1[i]);
    setValue(`emp2-y${i}`, model.employees.s2[i]);
  });
  setValue('project-cost-input', formatMoneyValue(model.projectCost));

  ['s1', 's2'].forEach(key => {
    [1, 2, 3].forEach(y => {
      setValue(`${key}-productivity-y${y}`, round(model.productivityTargetPct[key][y], 4));
      setValue(`${key}-nonlabour-y${y}`, round(model.efficiencyPct[key][y], 4));
    });
    const manual = document.getElementById(`${key}-manual-headcount`);
    if (manual) manual.checked = isManualHeadcount(model, key);
  });

  // Setting the charts recalculates both scenarios with the values above
  scenario1.setValues(model.revenuesK.s1);
  scenario2.setValues(model.revenuesK.s2);
  syncChartScales(model.revenuesK.s1[0]);
  recalcAll();
}

async function handleImportChange(e) {
  const input = e.target;
  const file = input.files[0];
  if (!file) return;
  try {
    if (!/\.xlsx$/i.test(file.name)) {
      throw new Error('Please choose an Excel workbook (.xlsx) exported from this app or based on the GVA Model template.');
    }
    const wb = new ExcelJS.Workbook();
    await wb.xlsx.load(await file.arrayBuffer());
    const model = readGvaWorkbook(wb);
    applyWorkbookModel(model);
    const notes = [];
    if (model.legacyLayout) notes.push('This workbook uses the older layout (no non-labour saving rows), so productivity targets were set to 0% and the version left blank.');
    if (model.depreciation.some(d => Math.round(d) !== Math.round(model.depreciation[0]))) {
      notes.push(`Depreciation differs between years in the workbook; Year 1 (${formatCurrencyK(model.depreciation[0] / 1000)}) is used as the baseline depreciation for every year. This doesn't change GVA, as depreciation is the same in both scenarios.`);
    }
    alert(notes.length ? `Import completed with notes:\n\n${notes.join('\n')}` : 'Import completed successfully!');
  } catch (err) {
    console.error(err);
    alert('Import failed: ' + err.message);
  }
  input.value = '';
}

/// What-if: a snapshot of every input is held in memory (never in browser storage) while a what-if
/// is open. Accept drops the snapshot; Discard puts every input and both charts back.
let whatIfSnapshot = null;

// Every data input on the page: scenarios, baseline, depreciation, comparison table and popups
function whatIfFields() {
  return Array.from(document.querySelectorAll('input, textarea, select'))
    .filter(f => f.id && !LOGIN_FIELD_IDS.includes(f.id) && f.type !== 'file');
}

function takeWhatIfSnapshot() {
  return {
    fields: whatIfFields().map(f => ({ id: f.id, value: f.value, checked: f.checked })),
    revenues: { s1: scenario1.getData().map(d => d.value), s2: scenario2.getData().map(d => d.value) },
    baselineNetProfitK
  };
}

function restoreWhatIfSnapshot(snap) {
  snap.fields.forEach(({ id, value, checked }) => {
    const f = document.getElementById(id);
    if (!f) return;
    if (f.type === 'checkbox' || f.type === 'radio') f.checked = checked;
    else f.value = value;
  });
  baselineNetProfitK = snap.baselineNetProfitK;
  scenario1.setValues(snap.revenues.s1);
  scenario2.setValues(snap.revenues.s2);
  syncChartScales(snap.revenues.s1[0]);
  recalcAll();
  updateSummaryTable();
  updateComparisonCalculations();
}

function setWhatIfMode(active) {
  document.body.classList.toggle('what-if-active', active);
  const bar = document.getElementById('what-if-bar');
  if (bar) bar.hidden = !active;
  const btn = document.getElementById('what-if-btn');
  if (btn) {
    btn.disabled = active;
    btn.setAttribute('aria-pressed', String(active));
  }
}

function startWhatIf() {
  if (whatIfSnapshot) return;
  whatIfSnapshot = takeWhatIfSnapshot();
  setWhatIfMode(true);
}

function acceptWhatIf() {
  whatIfSnapshot = null;
  setWhatIfMode(false);
}

function discardWhatIf() {
  if (whatIfSnapshot) restoreWhatIfSnapshot(whatIfSnapshot);
  whatIfSnapshot = null;
  setWhatIfMode(false);
}

const LOGIN_FIELD_IDS = ['login-username', 'login-password'];

// Browsers restore typed values on reload before scripts run; reset to the HTML defaults so no data carries over
function resetFormFieldsToDefaults() {
  document.querySelectorAll('input, textarea, select').forEach(field => {
    if (LOGIN_FIELD_IDS.includes(field.id) || field.type === 'file') return;
    field.setAttribute('autocomplete', 'off');
    if (field.type === 'checkbox' || field.type === 'radio') {
      field.checked = field.defaultChecked;
    } else if (field.tagName === 'SELECT') {
      Array.from(field.options).forEach(opt => { opt.selected = opt.defaultSelected; });
    } else {
      field.value = field.defaultValue;
    }
  });
}

// Deferred Dashboard Initialization function
function initializeDashboard() {
  resetFormFieldsToDefaults();
  initializeDynamicHeaders();

  scenario1 = createScenarioChart({
    svgId: 'chart1',
    summaryId: 'summary1',
    title: 'S1: No Grant',
    series: defaultRevenueSeries('s1').map((value, i) => ({ label: labels[i], value })),
    onUpdate: (data) => {
      if (scenario2) {
        const currentS2Data = scenario2.getData();
        if (currentS2Data[0].value !== data[0].value) {
          scenario2.setDataValue(0, data[0].value);
          syncChartScales(data[0].value);
        }
      }
      recalcScenario('s1');
    }
  });

  scenario2 = createScenarioChart({
    svgId: 'chart2',
    summaryId: 'summary2',
    title: 'S2: With Grant',
    series: defaultRevenueSeries('s2').map((value, i) => ({ label: labels[i], value })),
    onUpdate: (data) => {
      if (scenario1) {
        const currentS1Data = scenario1.getData();
        if (currentS1Data[0].value !== data[0].value) {
          scenario1.setDataValue(0, data[0].value);
          syncChartScales(data[0].value);
        }
      }
      recalcScenario('s2');
    }
  });

  baselineNetProfitK = DEFAULT_BASELINE_REVENUE_K * DEFAULT_BASELINE_MARGIN_PCT / 100;
  renderProfitPanel('s1');
  renderProfitPanel('s2');

  document.getElementById('emp1-baseline').addEventListener('input', handleBaselineEmployeesInput);
  // Formatting runs first so the recalculation reads the tidied value
  attachMoneyFormatting(document.getElementById('emp1-cost'));
  document.getElementById('emp1-cost').addEventListener('input', recalcAll);
  ['emp1', 'emp2'].forEach(prefix => {
    [1, 2, 3].forEach(yearIdx => {
      document.getElementById(`${prefix}-y${yearIdx}`)?.addEventListener('input', () => handleEmployeeYearInput(prefix, yearIdx));
    });
  });
  ['s1', 's2'].forEach(key => {
    [1, 2, 3].forEach(y => {
      document.getElementById(`${key}-productivity-y${y}`)?.addEventListener('input', () => recalcScenario(key));
      document.getElementById(`${key}-nonlabour-y${y}`)?.addEventListener('input', () => recalcScenario(key));
    });
    document.getElementById(`${key}-manual-headcount`)?.addEventListener('change', () => recalcScenario(key));
  });
  [1, 2, 3].forEach(idx => {
    document.getElementById(`upskilled-y${idx}`)?.addEventListener('input', updateUpskilledTotal);
  });
  updateUpskilledTotal();

  // £ inputs shown with thousands separators; formatting runs before the recalculation
  ['project-cost-input', 'dep-baseline'].forEach(id => {
    attachMoneyFormatting(document.getElementById(id));
    document.getElementById(id)?.addEventListener('input', updateSummaryTable);
  });

  // Bind Export/Import
  document.getElementById('export-btn').addEventListener('click', handleExport);
  document.getElementById('import-btn').addEventListener('click', handleImportClick);
  document.getElementById('import-file-input').addEventListener('change', handleImportChange);

  document.getElementById('what-if-btn')?.addEventListener('click', startWhatIf);
  document.getElementById('what-if-accept')?.addEventListener('click', acceptWhatIf);
  document.getElementById('what-if-discard')?.addEventListener('click', discardWhatIf);

  // Bind Modal
  document.getElementById('modal-apply-btn').addEventListener('click', handleApplyBaseline);
  document.getElementById('modal-skip-btn').addEventListener('click', handleSkipBaseline);
  document.getElementById('edit-baseline-btn').addEventListener('click', showBaselineModal);
  ['modal-profit', 'modal-emp-cost', 'modal-depreciation', 'modal-project-cost'].forEach(id => {
    attachMoneyFormatting(document.getElementById(id));
  });
  ['modal-revenue', 'modal-profit', 'modal-emp-cost'].forEach(id => {
    const el = document.getElementById(id);
    if (el) {
      el.addEventListener('input', validateBaselineModalInputs);
    }
  });

  COMP_KEYS.forEach(key => {
    const el = document.getElementById(key);
    if (el) {
      el.addEventListener('input', updateComparisonCalculations);
    }
  });
  updateComparisonCalculations();

  const clearCompBtn = document.getElementById('clear-comparison-btn');
  if (clearCompBtn) {
    clearCompBtn.addEventListener('click', clearComparisonInputs);
  }

  // Restore the side panel; sessions from before the switch only stored a collapsed flag
  let savedPanel = null;
  try {
    savedPanel = sessionStorage.getItem('gva_side_panel')
      || (sessionStorage.getItem('gva_sidebar_collapsed') === 'true' ? 'none' : null);
  } catch (e) { }
  applySidePanel(['summary', 'comparison', 'none'].includes(savedPanel) ? savedPanel : 'summary');

  scenario1.refresh();
  scenario2.refresh();
  syncChartScales(4500);
  updateSummaryTable();

  document.querySelectorAll('input, textarea, select').forEach(field => {
    if (!LOGIN_FIELD_IDS.includes(field.id)) field.setAttribute('autocomplete', 'off');
  });

  setTimeout(showBaselineModal, 300);
}

// Initialize Authentication Check
checkAuth();


function showInfoModal() {
  const modal = document.getElementById('infoModal');
  if (modal) modal.classList.add('active');
}

function hideInfoModal() {
  const modal = document.getElementById('infoModal');
  if (modal) modal.classList.remove('active');
}


function copySummaryToComparison() {
  const columns = ['baseline', 'y1', 'y2', 'y3'];
  columns.forEach((col, i) => {
    const s1Emp = document.getElementById(`comp-s1-emp-${col}`);
    const s1Prof = document.getElementById(`comp-s1-prof-${col}`);
    const s2Emp = document.getElementById(`comp-s2-emp-${col}`);
    const s2Prof = document.getElementById(`comp-s2-prof-${col}`);

    if (s1Emp) s1Emp.value = Number((employeeCostK.s1[i] || 0).toFixed(2));
    if (s1Prof) s1Prof.value = Number((netProfitK.s1[i] || 0).toFixed(2));
    if (s2Emp) s2Emp.value = Number((employeeCostK.s2[i] || 0).toFixed(2));
    if (s2Prof) s2Prof.value = Number((netProfitK.s2[i] || 0).toFixed(2));
  });

  const compProjCostEl = document.getElementById('comp-project-cost');
  if (compProjCostEl) {
    compProjCostEl.value = getProjectCostK();
  }

  updateComparisonCalculations();
}
